 district text,name text,address_line text,category text,phone text,tax_code text,source_key text,source_url text,verification_note text)
), ins AS (
 INSERT INTO public.field_prospects(id,area_visit_id,owner_sub,name,address_line,province,district,category,phone,tax_code,note,status,source_kind,research_source_key,research_source_url,research_batch)
 SELECT (substr(s.dg,1,8)||'-'||substr(s.dg,9,4)||'-5'||substr(s.dg,14,3)||'-8'||substr(s.dg,18,3)||'-'||substr(s.dg,21,12))::uuid,
 NULL,'ef943de4-18f7-49ef-8340-eefb18855534',
 s.name,s.address_line,'Tiền Giang',s.district,s.category,s.phone,s.tax_code,
 'Nghiên cứu nguồn công khai 21/11/2026; CHƯA GHÉ, GPS chưa xác minh; không mặc định còn bán lẻ. '||
 s.verification_note||' Nguồn: '||s.source_url,
 'new','manual',s.source_key,s.source_url,'2026-11-21-tien-giang-old-wave-02-four-districts'
 FROM src s
 WHERE s.district IN ('Thành phố Gò Công','Huyện Gò Công Đông','Huyện Gò Công Tây','Huyện Tân Phú Đông')
 AND s.source_url LIKE 'https://%'
 AND NOT EXISTS(SELECT 1 FROM public.customers c WHERE c.province='Tiền Giang' AND c.district=s.district
   AND lower(btrim(c.name))=lower(btrim(s.name)))
 AND NOT EXISTS(SELECT 1 FROM public.field_prospects p WHERE p.province='Tiền Giang' AND p.district=s.district
   AND (p.research_source_key=s.source_key OR
    (lower(btrim(p.name))=lower(btrim(s.name)) AND lower(btrim(p.address_line))=lower(btrim(s.address_line)))))
 ON CONFLICT (research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING
 RETURNING district,category,phone,tax_code
)
SELECT district,count(*)::int inserted,
 count(*) FILTER(WHERE category='nha_sach')::int bookstores,
 count(*) FILTER(WHERE category='van_phong_pham')::int vpp,
 count(*) FILTER(WHERE phone IS NOT NULL)::int phones,
 count(*) FILTER(WHERE tax_code IS NOT NULL)::int tax_codes
 FROM ins GROUP BY district ORDER BY district;